import{_ as i,o as a,c as t,ai as n}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"中间填充实验台","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/fim.md","filePath":"zh/guide/fim.md"}'),e={name:"zh/guide/fim.md"};function o(l,s,r,h,p,d){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="中间填充实验台" tabindex="-1">中间填充实验台 <a class="header-anchor" href="#中间填充实验台" aria-label="Permalink to &quot;中间填充实验台&quot;">​</a></h1><p><strong>FIM 实验台</strong>是一个小而专注的页面，用于测试<strong>代码补全式</strong>的生成。你提供一个<strong>前缀</strong>（光标之前的代码）和一个<strong>后缀</strong>（光标之后的代码），模型负责填补中间的空缺。</p><p><strong>侧边栏位置：</strong> 代码补全（在工具工坊下方） <strong>路由：</strong> <code>/fim</code><strong>加入版本：</strong> v0.4.7（2026 年 5 月）</p><h2 id="什么是中间填充" tabindex="-1">什么是中间填充？ <a class="header-anchor" href="#什么是中间填充" aria-label="Permalink to &quot;什么是中间填充？&quot;">​</a></h2><p>大多数对话 API 只支持从左到右的生成：你给出提示词，模型从你停下的地方继续往下写。<strong>FIM</strong> 不一样 —— 模型同时能看到空缺<em>之后</em>的内容，并写出自然衔接两端的内容。</p><p>GitHub Copilot 的行中建议、Cursor 的「Tab 补全」背后靠的就是这个能力。Ollama 提供的多个模型原生支持它：</p><ul><li><strong>Qwen2.5-Coder</strong>（全部尺寸）</li><li><strong>CodeLlama</strong>（<code>-code</code> 变体）</li><li><strong>Codestral</strong></li><li><strong>DeepSeek-Coder</strong></li><li><strong>StarCoder</strong></li></ul><p>Ollama 通过 <code>/api/generate</code> 接口上的 <code>suffix</code> 字段暴露 FIM 能力，LLMxRay 则把它呈现在 FIM 实验台页面中。</p><h2 id="使用这个页面" tabindex="-1">使用这个页面 <a class="header-anchor" href="#使用这个页面" aria-label="Permalink to &quot;使用这个页面&quot;">​</a></h2><ol><li>从下拉框选择模型 —— 具备编码能力的模型会优先列在「编码模型（支持 FIM）」分组下。</li><li>在左侧文本框输入你的<strong>前缀</strong>（光标之前的代码）。</li><li>在右侧文本框输入你的<strong>后缀</strong>（光标之后的代码）。</li><li>点击<strong>生成</strong>。</li></ol><p>模型会实时流式输出缺失的中间部分。生成完成后，你还会看到一个<strong>拼接预览</strong> —— 前缀、生成的中间内容（以强调色高亮）和后缀被渲染成一个连续的整体，让你能像在编辑器里那样通读整段结果。</p><h2 id="指标" tabindex="-1">指标 <a class="header-anchor" href="#指标" aria-label="Permalink to &quot;指标&quot;">​</a></h2><p>生成结束后，输出下方会出现四张指标卡片：</p><ul><li><strong>总耗时</strong> —— 从请求发出到最后一个 token 的实际时间</li><li><strong>模型加载</strong> —— Ollama 把模型载入内存所花的时间（热启动时为 0 ms）</li><li><strong>生成 token 数</strong> —— 模型为中间部分产出的 token 数量</li><li><strong>速度</strong> —— 每秒 token 数</li></ul><h2 id="如果模型不支持-fim" tabindex="-1">如果模型不支持 FIM <a class="header-anchor" href="#如果模型不支持-fim" aria-label="Permalink to &quot;如果模型不支持 FIM&quot;">​</a></h2><p>如果你选了一个非编码模型，页面会提前给出提示。若仍要尝试，Ollama 会返回一个明确的错误：<code>qwen2.5:3b does not support insert</code>（或类似内容，其中带有对应的模型名）。页面会把这个错误显示在输出区，而不会崩溃。</p><h2 id="幕后原理" tabindex="-1">幕后原理 <a class="header-anchor" href="#幕后原理" aria-label="Permalink to &quot;幕后原理&quot;">​</a></h2><p>页面调用 <code>/api/generate</code>，并带上 Ollama 提供的 <code>suffix</code> 字段：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;qwen2.5-coder:7b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prompt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;def fibonacci(n):</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    if n &lt;= 1:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        return n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;suffix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">print(fibonacci(10))&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>流式返回的 NDJSON 与普通对话的解析方式相同 —— 每行一个 JSON 对象，不断累积 <code>response</code> 增量，直到 <code>done: true</code>。</p><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./chat-diagnostics.html">对话诊断</a>：通用对话</li><li><a href="./tool-workshop.html">工具工坊</a>：构建 Agent 工具</li></ul>`,22)])])}const c=i(e,[["render",o]]);export{g as __pageData,c as default};
